from pathlib import Path
import json
import pandas as pd

PROJECT = Path(r"E:\quant-framework")


def _normalize_weights(weights: pd.Series, max_weight: float) -> dict:
    if weights.empty:
        return {}
    clipped = weights.clip(lower=0.0, upper=max_weight)
    total = float(clipped.sum())
    if total <= 0:
        return {}
    normalized = clipped / total
    if not normalized.empty and normalized.max() > max_weight + 1e-12:
        normalized = normalized.clip(upper=max_weight)
        normalized = normalized / normalized.sum()
    return {str(symbol): float(weight) for symbol, weight in normalized.items() if weight > 1e-12}


def _read_factor_table(path: str) -> pd.DataFrame:
    p = Path(path)
    if not p.exists():
        return pd.DataFrame()
    rows = json.loads(p.read_text(encoding="utf-8") or "[]")
    df = pd.DataFrame(rows)
    if df.empty or "symbol" not in df:
        return pd.DataFrame()
    return df.set_index("symbol")


def run(input, context):
    import sys
    sys.path.insert(0, str(PROJECT))
    from alphalab.strategy.config import StrategyConfig

    factor_result = input.get("factor_result") or {}
    data_result = input.get("data_result") or {}
    strategy_path = Path(input.get("strategy_path") or factor_result.get("strategy_path") or data_result.get("strategy_path") or PROJECT / "alphalab" / "strategies" / "momentum.yaml")
    if not strategy_path.is_absolute():
        strategy_path = PROJECT / strategy_path
    cfg = StrategyConfig.from_yaml(strategy_path)
    factors = _read_factor_table(factor_result.get("factors_path", ""))

    ranked_cols = []
    for spec in cfg.factors:
        if spec.name not in factors.columns:
            continue
        values = pd.to_numeric(factors[spec.name], errors="coerce").dropna()
        if values.empty:
            continue
        ranks = values.rank(pct=True)
        if spec.direction == "short":
            ranks = 1.0 - ranks
        ranked_cols.append((ranks * spec.weight).rename(spec.name))

    scores = pd.concat(ranked_cols, axis=1) if ranked_cols else pd.DataFrame()
    if scores.empty:
        weights = {}
        composite = pd.Series(dtype=float)
    else:
        coverage = scores.notna().mean(axis=1)
        scores = scores.loc[coverage >= cfg.selection.min_factor_coverage]
        composite = scores.sum(axis=1).sort_values(ascending=False) if not scores.empty else pd.Series(dtype=float)
        selected = composite.head(cfg.selection.n_stocks)
        weights = _normalize_weights(pd.Series(1.0, index=selected.index, dtype=float), cfg.portfolio.max_weight)

    run_dir = Path(factor_result.get("run_dir") or data_result.get("run_dir") or PROJECT / "data" / "app" / "pipeline_runs" / (factor_result.get("run_id") or "manual"))
    run_dir.mkdir(parents=True, exist_ok=True)
    out_path = run_dir / "target_weights.json"
    out_path.write_text(json.dumps(weights, ensure_ascii=False, indent=2), encoding="utf-8")

    as_of_date = input.get("as_of_date") or (data_result.get("params") or {}).get("as_of_date")
    return {
        "stage": "SignalEngine",
        "run_id": factor_result.get("run_id") or data_result.get("run_id"),
        "run_dir": str(run_dir),
        "strategy_path": str(strategy_path),
        "as_of_date": as_of_date,
        "target_weights": weights,
        "weights_path": str(out_path),
        "selected_symbols": list(weights.keys()),
        "diagnostics": {
            "strategy": cfg.name,
            "factor_columns_used": [c.name for c in ranked_cols],
            "score_count": int(len(composite)),
            "selected_count": int(len(weights)),
            "weight_sum": float(sum(weights.values())) if weights else 0.0,
        },
        "top_scores": composite.head(20).astype(float).to_dict() if not composite.empty else {},
    }
